using NavegacionShellMAUI.Data;
using NavegacionShellMAUI.Models;
namespace NavegacionShellMAUI.Views;
public partial class EditarCursoPage : ContentPage, IQueryAttributable { readonly CursoRepository repo; Curso? curso; public EditarCursoPage(CursoRepository repo){InitializeComponent();this.repo=repo;} public void ApplyQueryAttributes(IDictionary<string,object> query){curso=query.TryGetValue("curso",out var value)?value as Curso:null;if(curso is null)return;NombreEntry.Text=curso.Nombre;DescripcionEntry.Text=curso.Descripcion;InstructorEntry.Text=curso.Instructor;DuracionEntry.Text=curso.Duracion;CategoriaEntry.Text=curso.Categoria;NivelEntry.Text=curso.Nivel;CreditosEntry.Text=curso.Creditos.ToString();ErrorLabel.IsVisible=false;} async void GuardarClicked(object? sender,EventArgs e){if(curso is null){await DisplayAlertAsync("Error","No se recibió un curso válido.","Aceptar");return;}if(new[]{NombreEntry.Text,DescripcionEntry.Text,InstructorEntry.Text,DuracionEntry.Text,CategoriaEntry.Text,NivelEntry.Text}.Any(string.IsNullOrWhiteSpace)||!int.TryParse(CreditosEntry.Text,out var creditos)||creditos<0){ErrorLabel.Text="Completa todos los campos y proporciona créditos válidos.";ErrorLabel.IsVisible=true;return;}curso.Nombre=NombreEntry.Text!.Trim();curso.Descripcion=DescripcionEntry.Text!.Trim();curso.Instructor=InstructorEntry.Text!.Trim();curso.Duracion=DuracionEntry.Text!.Trim();curso.Categoria=CategoriaEntry.Text!.Trim();curso.Nivel=NivelEntry.Text!.Trim();curso.Creditos=creditos;repo.Actualizar(curso);await DisplayAlertAsync("Cambios guardados","El curso se actualizó correctamente.","Aceptar");await Shell.Current.GoToAsync("..");} async void CancelarClicked(object? sender,EventArgs e)=>await Shell.Current.GoToAsync(".."); }

